import hmac, os
from kyber_py.ml_kem import ML_KEM_512, ML_KEM_768, ML_KEM_1024
from dilithium_py.ml_dsa import ML_DSA_65

SETS = {"ML-KEM-512": ML_KEM_512, "ML-KEM-768": ML_KEM_768, "ML-KEM-1024": ML_KEM_1024}

class KemError(Exception):
    """One error type with no detail about WHY a decapsulation failed."""

class SecretBytes:
    """Holds secret material in a mutable buffer that can be wiped; repr never prints the content."""
    def __init__(self, data):
        self._buf = bytearray(data)
    def reveal(self):
        if self._buf is None:
            raise KemError("key destroyed")
        return bytes(self._buf)
    def destroy(self):
        for i in range(len(self._buf)):
            self._buf[i] = 0
        self._buf = None
    def __repr__(self):
        return "SecretBytes(<hidden>)"

class KemKeyPair:
    """A small, hard-to-misuse API: the algorithm is named in the object, sizes are checked, internals are not exposed."""
    def __init__(self, algorithm):
        if algorithm not in SETS:
            raise KemError("unknown algorithm")
        self.algorithm = algorithm
        self._kem = SETS[algorithm]
        ek, dk = self._kem.keygen()                                     # randomness is generated inside the module, never supplied by the caller
        self.public_key = (algorithm, ek)
        self._dk = SecretBytes(dk)
    def decapsulate(self, algorithm, ciphertext):
        if algorithm != self.algorithm or len(ciphertext) != 32 * (self._kem.du * self._kem.k + self._kem.dv):
            raise KemError("decapsulation failed")                      # the same message for every kind of failure
        return SecretBytes(self._kem.decaps(self._dk.reveal(), ciphertext))
    def destroy(self):
        self._dk.destroy()

def encapsulate(public_key):
    algorithm, ek = public_key
    kem = SETS[algorithm]
    if len(ek) != 384 * kem.k + 32:
        raise KemError("bad public key")
    key, ct = kem.encaps(ek)
    return (algorithm, ct), SecretBytes(key)

alice = KemKeyPair("ML-KEM-768")
(ct_alg, ct), key_b = encapsulate(alice.public_key)
key_a = alice.decapsulate(ct_alg, ct)
print("honest exchange:", hmac.compare_digest(key_a.reveal(), key_b.reveal()), "| repr hides content:", repr(key_a))

def attempt(label, action):
    try:
        action()
        print(f"{label:<54} accepted")
    except KemError as exc:
        print(f"{label:<54} KemError: {exc}")
    except Exception as exc:
        print(f"{label:<54} {type(exc).__name__}")
attempt("ciphertext for a different parameter set", lambda: alice.decapsulate("ML-KEM-512", ct))
attempt("truncated ciphertext", lambda: alice.decapsulate(ct_alg, ct[:-1]))
attempt("unknown algorithm name", lambda: KemKeyPair("ML-KEM-999"))
attempt("public key of the wrong length", lambda: encapsulate(("ML-KEM-768", alice.public_key[1][:-1])))
tampered = bytearray(ct); tampered[0] ^= 1
other = alice.decapsulate(ct_alg, bytes(tampered))
print("tampered ciphertext does not raise and gives a different key:", other.reveal() != key_a.reveal())
alice.destroy()
attempt("use after destroy", lambda: alice.decapsulate(ct_alg, ct))
print("design rules visible in the code: one opaque key type per algorithm, algorithm name bound to every key and ciphertext, internal (deterministic) functions not exported, a single undifferentiated error for failed decapsulation, secrets in wipeable buffers")
print("constant-time comparison of secrets uses hmac.compare_digest instead of ==")
